export interface DrawingState {
  color: string;
  brushSize: number;
}

export interface GenerationConfig {
  prompt: string;
  style: string;
  model: string;
}

export interface GeneratedLogo {
  mediaId: string;
  base64: string;
  mimeType: string;
}

import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';

interface DrawingCanvasProps {
  color: string;
  brushSize: number;
  onDraw?: () => void;
}

export interface DrawingCanvasHandle {
  clear: () => void;
  getCanvas: () => HTMLCanvasElement | null;
}

export const DrawingCanvas = forwardRef<DrawingCanvasHandle, DrawingCanvasProps>(({ color, brushSize, onDraw }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    // Set display size
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;

    const context = canvas.getContext('2d');
    if (context) {
      context.scale(window.devicePixelRatio, window.devicePixelRatio);
      context.lineCap = 'round';
      context.lineJoin = 'round';
      context.strokeStyle = color;
      context.lineWidth = brushSize;
      contextRef.current = context;

      // Fill initial white background for better AI reference
      context.fillStyle = 'white';
      context.fillRect(0, 0, canvas.width, canvas.height);
    }
  }, []);

  useEffect(() => {
    if (contextRef.current) {
      contextRef.current.strokeStyle = color;
      contextRef.current.lineWidth = brushSize;
    }
  }, [color, brushSize]);

  useImperativeHandle(ref, () => ({
    clear: () => {
      const canvas = canvasRef.current;
      const context = contextRef.current;
      if (canvas && context) {
        context.fillStyle = 'white';
        context.fillRect(0, 0, canvas.width, canvas.height);
      }
    },
    getCanvas: () => canvasRef.current
  }));

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    const { offsetX, offsetY } = getCoordinates(e);
    contextRef.current?.beginPath();
    contextRef.current?.moveTo(offsetX, offsetY);
    setIsDrawing(true);
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const { offsetX, offsetY } = getCoordinates(e);
    contextRef.current?.lineTo(offsetX, offsetY);
    contextRef.current?.stroke();
    onDraw?.();
  };

  const stopDrawing = () => {
    contextRef.current?.closePath();
    setIsDrawing(false);
  };

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    if ('nativeEvent' in e && e.nativeEvent instanceof MouseEvent) {
      return { offsetX: e.nativeEvent.offsetX, offsetY: e.nativeEvent.offsetY };
    } else {
      const touch = (e as React.TouchEvent).touches[0];
      const rect = (e.target as HTMLCanvasElement).getBoundingClientRect();
      return {
        offsetX: touch.clientX - rect.left,
        offsetY: touch.clientY - rect.top
      };
    }
  };

  return (
    <div className="relative w-full h-full bg-white rounded-2xl overflow-hidden cursor-crosshair shadow-inner border border-white/10">
      <canvas
        ref={canvasRef}
        onMouseDown={startDrawing}
        onMouseMove={draw}
        onMouseUp={stopDrawing}
        onMouseLeave={stopDrawing}
        onTouchStart={startDrawing}
        onTouchMove={draw}
        onTouchEnd={stopDrawing}
        className="w-full h-full touch-none"
      />
    </div>
  );
});

import React from 'react';
import { SectionLabel, PillButton, FieldDropdown, DragNumberField, TextInput } from './Primitives';

interface SidebarProps {
  brushSize: number;
  setBrushSize: (v: number) => void;
  brushColor: string;
  setBrushColor: (v: string) => void;
  prompt: string;
  setPrompt: (v: string) => void;
  style: string;
  setStyle: (v: string) => void;
  isGenerating: boolean;
  onGenerate: () => void;
  onClear: () => void;
  onDownload: () => void;
  hasResult: boolean;
}

const COLORS = [
  { name: 'Black', hex: '#000000' },
  { name: 'Red', hex: '#ef4444' },
  { name: 'Blue', hex: '#3b82f6' },
  { name: 'Green', hex: '#22c55e' },
  { name: 'Eraser', hex: '#ffffff' },
];

const LOGO_STYLES = [
  'Professional Minimalist',
  'Modern Tech Vector',
  'Luxury Emblem',
  'Playful Mascot',
  'Vintage Badge',
  'Abstract Geometry',
  'Hand-drawn Organic'
];

export const Sidebar: React.FC<SidebarProps> = ({
  brushSize, setBrushSize,
  brushColor, setBrushColor,
  prompt, setPrompt,
  style, setStyle,
  isGenerating, onGenerate,
  onClear, onDownload,
  hasResult
}) => {
  return (
    <div className="relative border border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e]">
      <div className="flex flex-col gap-[24px] items-start w-full">

        {/* Drawing Tools */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Drawing tools</SectionLabel>
          <div className="flex flex-col gap-1.5 items-start w-full">
             <div className="flex gap-1 w-full h-[49px]">
               <FieldDropdown 
                label="Brush color" 
                value={COLORS.find(c => c.hex === brushColor)?.name || 'Custom'} 
                options={COLORS.map(c => c.name)}
                onChange={(name) => setBrushColor(COLORS.find(c => c.name === name)?.hex || '#000000')}
                className="flex-1"
              />
              <DragNumberField 
                label="Size" 
                value={brushSize} 
                min={1} max={50} 
                onChange={setBrushSize} 
                className="flex-1" 
              />
            </div>
            <PillButton 
              variant="outline" 
              icon={<span className="material-symbols-outlined text-[18px]">restart_alt</span>}
              onClick={onClear}
            >
              Clear Canvas
            </PillButton>
          </div>
        </div>

        {/* Instructions */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Design instructions</SectionLabel>
          <div className="flex flex-col gap-1.5 items-start w-full">
            <FieldDropdown 
              label="Logo Style" 
              value={style} 
              options={LOGO_STYLES}
              onChange={setStyle}
              className="w-full"
            />
            <TextInput 
              value={prompt} 
              onChange={setPrompt} 
              placeholder="Describe your logo instructions (e.g., 'A modern tech company logo for a space startup, sleek metallic finish')..." 
            />
          </div>
        </div>

      </div>

      {/* Actions */}
      <div className="flex flex-col gap-[5px] items-start w-full pt-2">
        <PillButton 
          variant="solid" 
          icon={<span className="material-symbols-outlined text-[18px]">{isGenerating ? 'refresh' : 'auto_awesome'}</span>}
          onClick={onGenerate}
          disabled={isGenerating}
        >
          {isGenerating ? 'Architecting...' : 'Generate Logo'}
        </PillButton>
        {hasResult && (
          <PillButton 
            variant="outline" 
            icon={<span className="material-symbols-outlined text-[18px]">download</span>}
            onClick={onDownload}
          >
            Export PNG
          </PillButton>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { document.removeEventListener('mousedown', listener); document.removeEventListener('touchstart', listener); };
  }, [ref, handler]);
}

export const FieldDropdown: React.FC<{
  label: string; value: string; options: string[];
  onChange: (val: string) => void; className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const DragNumberField: React.FC<{
  label: string; value: number; min?: number; max?: number;
  step?: number; suffix?: string; onChange: (val: number) => void; className?: string;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = 'px', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value}{suffix}</span>
            <div className="flex flex-col items-center mr-1.5 -gap-px text-white/40">
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 0L9 5H1L5 0Z" fill="currentColor"/></svg>
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 6L1 1H9L5 6Z" fill="currentColor"/></svg>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export const TextInput: React.FC<{
  value: string; onChange: (val: string) => void; placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[80px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.75)] tracking-[0.1px] focus:outline-none transition-colors dark-scrollbar" />
);

import React, { useState, useRef, useEffect } from 'react';
import { DrawingCanvas, DrawingCanvasHandle } from './components/DrawingCanvas';
import { Sidebar } from './components/Sidebar';
import { GeneratedLogo } from './types';
import { Flow } from 'flow-sdk';

export default function App() {
  const [brushSize, setBrushSize] = useState(5);
  const [brushColor, setBrushColor] = useState('#000000');
  const [prompt, setPrompt] = useState('');
  const [style, setStyle] = useState('Professional Minimalist');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GeneratedLogo | null>(null);
  const [error, setError] = useState<string | null>(null);

  const canvasRef = useRef<DrawingCanvasHandle>(null);

  useEffect(() => {
    const id = 'flow-global-styles';
    if (document.getElementById(id)) return;
    const styleTag = document.createElement('style');
    styleTag.id = id;
    styleTag.textContent = `
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }
      html, body, #root { height: 100%; margin: 0; overflow: hidden; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; }
    `;
    document.head.appendChild(styleTag);
  }, []);

  const handleGenerate = async () => {
    const canvas = canvasRef.current?.getCanvas();
    if (!canvas) return;

    setIsGenerating(true);
    setError(null);

    try {
      // 1. Upload the doodle
      const base64 = canvas.toDataURL('image/png').split(',')[1];
      const uploaded = await Flow.upload({
        base64,
        mimeType: 'image/png',
        name: 'Logo Sketch'
      });

      // 2. Generate logo using doodle as reference
      // Defaulting to 🍌 Nano Banana Pro for best balance of I2I capability
      const fullPrompt = `A professional logo for ${prompt || 'a new brand'}. Style: ${style}. High quality vector art, clean lines, professional branding, solid background. Inspired by the provided sketch structure.`;

      const generation = await Flow.generate.image({
        prompt: fullPrompt,
        referenceImageMediaIds: [uploaded.mediaId],
        aspectRatio: '1:1',
        modelDisplayName: '🍌 Nano Banana Pro'
      });

      setResult(generation);
    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : 'Generation failed. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = async () => {
    if (!result) return;
    await Flow.download({
      base64: result.base64,
      mimeType: result.mimeType,
      filename: `Logo_${Date.now()}.png`
    });
  };

  const clearAll = () => {
    canvasRef.current?.clear();
    setResult(null);
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      <Sidebar 
        brushSize={brushSize}
        setBrushSize={setBrushSize}
        brushColor={brushColor}
        setBrushColor={setBrushColor}
        prompt={prompt}
        setPrompt={setPrompt}
        style={style}
        setStyle={setStyle}
        isGenerating={isGenerating}
        onGenerate={handleGenerate}
        onClear={clearAll}
        onDownload={handleDownload}
        hasResult={!!result}
      />

      <main className="flex-1 flex flex-col p-6 gap-6 min-w-0">
        <div className="flex-1 flex flex-col lg:flex-row gap-6 min-h-0">
          {/* Sketching Area */}
          <div className="flex-1 flex flex-col gap-3 min-h-0">
            <div className="flex items-center justify-between px-2">
              <h2 className="text-sm font-medium text-white/60 flex items-center gap-2">
                <span className="material-symbols-outlined text-[18px]">brush</span>
                Doodle your sketch
              </h2>
            </div>
            <div className="flex-1 relative min-h-0">
              <DrawingCanvas 
                ref={canvasRef}
                color={brushColor}
                brushSize={brushSize}
              />
            </div>
          </div>

          {/* Result Area */}
          <div className="flex-1 flex flex-col gap-3 min-h-0">
            <div className="flex items-center justify-between px-2">
              <h2 className="text-sm font-medium text-white/60 flex items-center gap-2">
                <span className="material-symbols-outlined text-[18px]">auto_awesome</span>
                Architected Result
              </h2>
            </div>
            <div className="flex-1 bg-black/40 rounded-2xl border border-white/5 overflow-hidden flex items-center justify-center relative min-h-0">
              {isGenerating ? (
                <div className="flex flex-col items-center gap-4 animate-pulse">
                  <div className="w-12 h-12 rounded-full border-2 border-t-white border-white/10 animate-spin" />
                  <p className="text-xs text-white/40 tracking-wider">TRANSFORMING SKETCH...</p>
                </div>
              ) : result ? (
                <img 
                  src={`data:${result.mimeType};base64,${result.base64}`} 
                  alt="Generated Logo" 
                  className="max-w-full max-h-full object-contain shadow-2xl"
                />
              ) : (
                <div className="flex flex-col items-center gap-2 text-white/20">
                  <span className="material-symbols-outlined text-[48px]">architecture</span>
                  <p className="text-xs">Sketch something and click Generate</p>
                </div>
              )}

              {error && (
                <div className="absolute bottom-4 left-4 right-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-[11px] backdrop-blur-md">
                  {error}
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}
